package io.github.finalparadox.client;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import io.github.finalparadox.entity.RuinHammerSwingEntity;import net.minecraft.client.renderer.MultiBufferSource;import net.minecraft.client.renderer.block.BlockRenderDispatcher;import net.minecraft.client.renderer.entity.EntityRenderer;import net.minecraft.client.renderer.entity.EntityRendererProvider;import net.minecraft.client.renderer.entity.ItemRenderer;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.inventory.InventoryMenu;import net.minecraft.world.item.ItemDisplayContext;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.Items;import net.minecraft.world.level.block.Blocks;
public final class RuinHammerSwingRenderer extends EntityRenderer<RuinHammerSwingEntity>{private final BlockRenderDispatcher blocks;private final ItemRenderer items;public RuinHammerSwingRenderer(EntityRendererProvider.Context c){super(c);blocks=c.getBlockRenderDispatcher();items=c.getItemRenderer();shadowRadius=0;}@Override public ResourceLocation getTextureLocation(RuinHammerSwingEntity e){return InventoryMenu.BLOCK_ATLAS;}@Override public void render(RuinHammerSwingEntity e,float y,float p,PoseStack pose,MultiBufferSource b,int l){pose.pushPose();pose.mulPose(Axis.YP.rotationDegrees(-e.getYRot()));pose.pushPose();pose.translate(.6,-.7,1.1);pose.mulPose(Axis.XP.rotationDegrees(90));pose.scale(2.4F,2.4F,2.4F);items.renderStatic(new ItemStack(Items.STICK),ItemDisplayContext.FIXED,l,OverlayTexture.NO_OVERLAY,pose,b,e.level(),e.getId());pose.popPose();block(pose,b,l,Blocks.LODESTONE,.5,-.7,2,1F);block(pose,b,l,Blocks.POLISHED_BASALT,.3,.2,2.2,.8F);block(pose,b,l,Blocks.LODESTONE,1.2,-.7,2,.8F);pose.popPose();super.render(e,y,p,pose,b,l);}private void block(PoseStack p,MultiBufferSource b,int l,net.minecraft.world.level.block.Block block,double x,double y,double z,float s){p.pushPose();p.translate(x,y,z);p.mulPose(Axis.YP.rotationDegrees(45));p.scale(s,s,s);p.translate(-.5,-.5,-.5);blocks.renderSingleBlock(block.defaultBlockState(),p,b,l,OverlayTexture.NO_OVERLAY);p.popPose();}}
